/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::5d85098b4ac6cafcaf494c6e12dc9ca1d59bdd6e41040e1ea1eb49e69ad14660 */
/* QuickSight 9dc5c359-8fb7-40b6-9ebf-2a90600bd531 */
SELECT "cedc0063-a6c4-46b7-befb-c175092706ad.cppib_security_id"
FROM (
SELECT "cppib_security_id" AS "cedc0063-a6c4-46b7-befb-c175092706ad.cppib_security_id", DENSE_RANK() OVER (PARTITION BY "cppib_security_id" ORDER BY "cppib_security_id" NULLS FIRST) AS "$RANK_1"
FROM "AwsDataCatalog"."risk_prod"."rmv_position"
WHERE "investment_dept" = 'Credit Investments' AND "cppib_security_id" IN ('O365_E5_Users', 'AWS_SSO_ReadOnly_Risk', 'AWS_SSO_QS_Viewer_Risk')
GROUP BY "cppib_security_id"
) AS "t"
WHERE "$RANK_1" <= 1001

